DDL = "\nCREATE TABLE cehub_project.value_measurement_studies (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tcreator_user_id UUID NOT NULL, \n\ttitle VARCHAR(256) NOT NULL, \n\tprotocol JSONB NOT NULL, \n\tprotocol_digest VARCHAR(64) NOT NULL, \n\tevidence_kind VARCHAR(32) NOT NULL, \n\twindow_start TIMESTAMP WITH TIME ZONE NOT NULL, \n\twindow_end TIMESTAMP WITH TIME ZONE NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_value_measurement_studies PRIMARY KEY (id), \n\tCONSTRAINT fk_value_study_project FOREIGN KEY(tenant_id, project_id) REFERENCES cehub_project.projects (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_study_creator FOREIGN KEY(tenant_id, creator_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_value_study_scope UNIQUE (tenant_id, project_id, id), \n\tCONSTRAINT uq_value_study_request UNIQUE (tenant_id, creator_user_id, request_id), \n\tCONSTRAINT ck_value_measurement_studies_window_order CHECK (window_end > window_start), \n\tCONSTRAINT ck_value_measurement_studies_evidence_kind CHECK (evidence_kind IN ('real_business','controlled_replay','synthetic')), \n\tCONSTRAINT ck_value_measurement_studies_real_preregistered CHECK (evidence_kind <> 'real_business' OR window_start > created_at), \n\tCONSTRAINT ck_value_measurement_studies_protocol_object CHECK (jsonb_typeof(protocol)='object' AND protocol->>'evidence_kind'=evidence_kind), \n\tCONSTRAINT ck_value_measurement_studies_digests CHECK (protocol_digest ~ '^[a-f0-9]{64}$' AND request_digest ~ '^[a-f0-9]{64}$')\n)\n\n;\nCREATE INDEX ix_value_study_project ON cehub_project.value_measurement_studies (tenant_id, project_id, id);\n\nCREATE TABLE cehub_project.value_measurement_consents (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tstudy_id UUID NOT NULL, \n\tparticipant_user_id UUID NOT NULL, \n\tversion INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tactivity_and_aggregate_use_confirmed BOOLEAN NOT NULL, \n\treason TEXT NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_value_measurement_consents PRIMARY KEY (id), \n\tCONSTRAINT fk_value_consent_study FOREIGN KEY(tenant_id, project_id, study_id) REFERENCES cehub_project.value_measurement_studies (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_consent_participant FOREIGN KEY(tenant_id, participant_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_value_consent_scope UNIQUE (tenant_id, project_id, study_id, participant_user_id, id), \n\tCONSTRAINT uq_value_consent_version UNIQUE (tenant_id, study_id, participant_user_id, version), \n\tCONSTRAINT uq_value_consent_request UNIQUE (tenant_id, participant_user_id, request_id), \n\tCONSTRAINT ck_value_measurement_consents_version_status CHECK (version > 0 AND status IN ('consented','withdrawn')), \n\tCONSTRAINT ck_value_measurement_consents_explicit_consent CHECK (status <> 'consented' OR activity_and_aggregate_use_confirmed), \n\tCONSTRAINT ck_value_measurement_consents_reason_digest CHECK (btrim(reason)<>'' AND request_digest ~ '^[a-f0-9]{64}$')\n)\n\n;\nCREATE INDEX ix_value_consent_current ON cehub_project.value_measurement_consents (tenant_id, study_id, participant_user_id, version);\n\nCREATE TABLE cehub_project.value_measurement_samples (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tstudy_id UUID NOT NULL, \n\tsample_id UUID NOT NULL, \n\tversion INTEGER NOT NULL, \n\tparticipant_user_id UUID NOT NULL, \n\tconsent_id UUID NOT NULL, \n\ttask_id UUID NOT NULL, \n\tevidence_document_id UUID, \n\tmode VARCHAR(24) NOT NULL, \n\tbody JSONB NOT NULL, \n\tsource_snapshot JSONB NOT NULL, \n\tsource_digest VARCHAR(64) NOT NULL, \n\treason TEXT NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_value_measurement_samples PRIMARY KEY (id), \n\tCONSTRAINT fk_value_sample_study FOREIGN KEY(tenant_id, project_id, study_id) REFERENCES cehub_project.value_measurement_studies (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_sample_consent FOREIGN KEY(tenant_id, project_id, study_id, participant_user_id, consent_id) REFERENCES cehub_project.value_measurement_consents (tenant_id, project_id, study_id, participant_user_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_sample_participant FOREIGN KEY(tenant_id, participant_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_sample_task FOREIGN KEY(tenant_id, project_id, task_id) REFERENCES cehub_project.tasks (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_sample_document FOREIGN KEY(tenant_id, project_id, evidence_document_id) REFERENCES cehub_project.documents (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_value_sample_scope UNIQUE (tenant_id, project_id, id), \n\tCONSTRAINT uq_value_sample_version UNIQUE (tenant_id, sample_id, version), \n\tCONSTRAINT uq_value_sample_task_revision UNIQUE (tenant_id, study_id, participant_user_id, task_id, mode, version), \n\tCONSTRAINT uq_value_sample_request UNIQUE (tenant_id, participant_user_id, request_id), \n\tCONSTRAINT ck_value_measurement_samples_version_mode CHECK (version > 0 AND mode IN ('baseline_without_ai','assisted')), \n\tCONSTRAINT ck_value_measurement_samples_objects CHECK (jsonb_typeof(body)='object' AND jsonb_typeof(source_snapshot)='object'), \n\tCONSTRAINT ck_value_measurement_samples_body_identity CHECK (body->>'participant_user_id'=participant_user_id::text AND body->>'sample_id'=sample_id::text AND body->>'study_id'=study_id::text AND body->>'task_id'=task_id::text AND body->>'mode'=mode), \n\tCONSTRAINT ck_value_measurement_samples_reason_digests CHECK (source_digest ~ '^[a-f0-9]{64}$' AND request_digest ~ '^[a-f0-9]{64}$' AND btrim(reason)<>'')\n)\n\n;\nCREATE INDEX ix_value_sample_current ON cehub_project.value_measurement_samples (tenant_id, study_id, sample_id, version);"

GUARDS = "\nCREATE FUNCTION cehub_project.guard_value_consent() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE previous cehub_project.value_measurement_consents;\nBEGIN\n PERFORM 1 FROM cehub_project.projects WHERE tenant_id=NEW.tenant_id AND id=NEW.project_id FOR UPDATE;\n SELECT * INTO previous FROM cehub_project.value_measurement_consents WHERE tenant_id=NEW.tenant_id AND study_id=NEW.study_id AND participant_user_id=NEW.participant_user_id ORDER BY version DESC LIMIT 1;\n IF NEW.version<>coalesce(previous.version,0)+1 OR (previous.id IS NULL AND NEW.status<>'consented')\n THEN RAISE EXCEPTION 'Participant consent must append the next explicit version'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_project.guard_value_sample() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE study cehub_project.value_measurement_studies;\nDECLARE grant_row cehub_project.value_measurement_consents;\nDECLARE previous cehub_project.value_measurement_samples;\nDECLARE began timestamptz;\nDECLARE observed timestamptz;\nDECLARE ended timestamptz;\nDECLARE immutable_key text;\nBEGIN\n PERFORM 1 FROM cehub_project.projects WHERE tenant_id=NEW.tenant_id AND id=NEW.project_id FOR UPDATE;\n SELECT * INTO study FROM cehub_project.value_measurement_studies WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.study_id;\n SELECT * INTO grant_row FROM cehub_project.value_measurement_consents WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND study_id=NEW.study_id AND participant_user_id=NEW.participant_user_id ORDER BY version DESC LIMIT 1;\n IF study.id IS NULL OR grant_row.id IS DISTINCT FROM NEW.consent_id OR grant_row.status IS DISTINCT FROM 'consented' OR NOT grant_row.activity_and_aggregate_use_confirmed THEN RAISE EXCEPTION 'Measurement requires current personal consent in the same study'; END IF;\n IF NEW.body->>'participant_user_id' IS DISTINCT FROM NEW.participant_user_id::text OR NEW.body->>'sample_id' IS DISTINCT FROM NEW.sample_id::text\n  OR NEW.body->>'study_id' IS DISTINCT FROM NEW.study_id::text OR NEW.body->>'task_id' IS DISTINCT FROM NEW.task_id::text\n  OR NEW.body->>'mode' IS DISTINCT FROM NEW.mode OR NEW.body->>'evidence_kind' IS DISTINCT FROM study.evidence_kind\n  OR NEW.body->>'scenario_id' IS DISTINCT FROM study.protocol->>'scenario_id'\n  OR NEW.body->>'evidence_document_id' IS DISTINCT FROM NEW.evidence_document_id::text\n  OR NOT coalesce(study.protocol->'role_ids' ? (NEW.body->>'role_id'),false)\n  OR NOT coalesce(study.protocol->'complexity_strata' ? (NEW.body->>'complexity_stratum'),false)\n THEN RAISE EXCEPTION 'Sample identity and registered stratum must match'; END IF;\n began=(NEW.body->>'started_at')::timestamptz;\n observed=(NEW.body->>'as_of')::timestamptz;\n ended=(NEW.body->>'ended_at')::timestamptz;\n IF began IS NULL OR observed IS NULL OR began<study.window_start OR began>=study.window_end OR observed<began OR observed>NEW.created_at OR (ended IS NOT NULL AND (ended<began OR ended>observed))\n THEN RAISE EXCEPTION 'Sample must preserve actual observation interval and study start window'; END IF;\n IF study.evidence_kind='real_business' AND (study.created_at>=began OR grant_row.created_at>began OR NOT EXISTS(SELECT 1 FROM cehub_project.tasks WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.task_id AND created_at<=began))\n THEN RAISE EXCEPTION 'Real observations require preregistered protocol, personal consent and actual prior task'; END IF;\n IF NEW.body->>'excluded_rule_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(study.protocol->'exclusion_rules') x WHERE x->>'rule_id'=NEW.body->>'excluded_rule_id')\n THEN RAISE EXCEPTION 'Exclusion must name a preregistered rule'; END IF;\n IF jsonb_typeof(NEW.body->'segments') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.body->'segments') x WHERE x->>'participant_user_id' IS DISTINCT FROM NEW.participant_user_id::text)\n THEN RAISE EXCEPTION 'Activity segments must belong to the named participant'; END IF;\n IF study.evidence_kind='real_business' AND EXISTS(SELECT 1 FROM cehub_project.value_measurement_samples WHERE tenant_id=NEW.tenant_id AND study_id=NEW.study_id AND participant_user_id=NEW.participant_user_id AND task_id=NEW.task_id AND sample_id<>NEW.sample_id) THEN RAISE EXCEPTION 'A real task cannot become another independent observation'; END IF;\n SELECT * INTO previous FROM cehub_project.value_measurement_samples WHERE tenant_id=NEW.tenant_id AND sample_id=NEW.sample_id ORDER BY version DESC LIMIT 1;\n IF NEW.version<>coalesce(previous.version,0)+1 THEN RAISE EXCEPTION 'Sample revision must append the next version'; END IF;\n IF previous.id IS NOT NULL THEN\n  IF observed<(previous.body->>'as_of')::timestamptz THEN RAISE EXCEPTION 'New observation cutoff cannot precede original cutoff'; END IF;\n  IF NEW.project_id IS DISTINCT FROM previous.project_id OR NEW.study_id IS DISTINCT FROM previous.study_id OR NEW.participant_user_id IS DISTINCT FROM previous.participant_user_id OR NEW.task_id IS DISTINCT FROM previous.task_id OR NEW.mode IS DISTINCT FROM previous.mode\n  THEN RAISE EXCEPTION 'Cannot move a sample to another participant, task or study'; END IF;\n  FOREACH immutable_key IN ARRAY ARRAY['study_id','sample_id','task_id','role_id','complexity_stratum','mode','pair_key','matching_basis','first_use','workflow_version','started_at'] LOOP\n   IF NEW.body->immutable_key IS DISTINCT FROM previous.body->immutable_key THEN RAISE EXCEPTION 'Sample comparison identity cannot be rewritten'; END IF;\n  END LOOP;\n END IF;\n RETURN NEW;\nEND $$;\n"

